USE [golden_db];
SET XACT_ABORT ON;
SET LOCK_TIMEOUT 30000;
BEGIN TRY
BEGIN TRANSACTION;
ALTER TABLE [dbo].[order_lines] DROP CONSTRAINT [FK_order_lines_orders];
DROP INDEX [IX_order_lines_order] ON [dbo].[order_lines];
ALTER TABLE [dbo].[orders] DROP CONSTRAINT [PK_orders];
ALTER TABLE [dbo].[order_lines] ALTER COLUMN [order_code] varchar(20) COLLATE Latin1_General_100_CS_AS NOT NULL;
ALTER TABLE [dbo].[orders] ALTER COLUMN [code] varchar(20) COLLATE Latin1_General_100_CS_AS NOT NULL;
CREATE NONCLUSTERED INDEX [IX_order_lines_order] ON [dbo].[order_lines] ([order_code] ASC) WITH (PAD_INDEX = OFF, IGNORE_DUP_KEY = OFF, STATISTICS_NORECOMPUTE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, DATA_COMPRESSION = NONE) ON [PRIMARY];
ALTER TABLE [dbo].[orders] ADD CONSTRAINT [PK_orders] PRIMARY KEY CLUSTERED ([code] ASC) WITH (PAD_INDEX = OFF, IGNORE_DUP_KEY = OFF, STATISTICS_NORECOMPUTE = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, DATA_COMPRESSION = NONE) ON [PRIMARY];
ALTER TABLE [dbo].[order_lines] WITH CHECK ADD CONSTRAINT [FK_order_lines_orders] FOREIGN KEY ([order_code]) REFERENCES [dbo].[orders] ([code]) ON DELETE NO ACTION ON UPDATE CASCADE;
COMMIT TRANSACTION;
END TRY
BEGIN CATCH
IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
THROW;
END CATCH;
